import { Link } from 'react-router-dom';
import { Menu, X } from 'lucide-react';
import { useState, useEffect } from 'react';

export default function Header() {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isScrolled, setIsScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => setIsScrolled(window.scrollY > 40);
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const navItems = [
    { href: '#about', label: 'About' },
    { href: '#contact', label: 'Contact' },
  ];

  const handleNavClick = (href: string) => {
    setIsMobileMenuOpen(false);
    if (href.startsWith('#')) {
      const el = document.querySelector(href);
      if (el) el.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return (
    <header
      className={`fixed top-0 left-0 right-0 z-50 transition-all duration-500 ${
        isScrolled
          ? 'bg-background/95 backdrop-blur-md border-b border-border/40'
          : 'bg-transparent'
      }`}
    >
      <div className="container mx-auto px-6 md:px-10">
        <div className="flex h-20 items-center justify-between">
          {/* Logo */}
          <Link to="/" className="flex items-center shrink-0" aria-label="Home">
            <img
              src="/airo-assets/images/logo/horizontal"
              alt="AJ logo"
              className="h-8 w-auto object-contain"
            />
          </Link>

          {/* Desktop Nav */}
          <nav className="hidden md:flex items-center gap-10">
            {navItems.map((item) => (
              <button
                key={item.href}
                onClick={() => handleNavClick(item.href)}
                className="group relative text-sm font-medium tracking-widest uppercase text-foreground/70 hover:text-foreground transition-colors duration-300"
              >
                {item.label}
                <span className="absolute -bottom-0.5 left-0 h-px w-0 bg-primary transition-all duration-300 group-hover:w-full" />
              </button>
            ))}
            <button
              onClick={() => handleNavClick('#contact')}
              className="text-sm font-medium tracking-widest uppercase text-primary border border-primary/40 px-5 py-2 hover:bg-primary hover:text-background transition-all duration-300"
            >
              Hire Me
            </button>
          </nav>

          {/* Mobile toggle */}
          <button
            onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
            className="md:hidden p-2 text-foreground/70 hover:text-foreground transition-colors"
            aria-label="Toggle menu"
          >
            {isMobileMenuOpen ? <X size={22} /> : <Menu size={22} />}
          </button>
        </div>

        {/* Mobile menu */}
        {isMobileMenuOpen && (
          <div className="md:hidden border-t border-border/30 py-6 bg-background/95 backdrop-blur-md">
            <nav className="flex flex-col gap-4">
              {navItems.map((item) => (
                <button
                  key={item.href}
                  onClick={() => handleNavClick(item.href)}
                  className="text-left text-sm font-medium tracking-widest uppercase text-foreground/70 hover:text-foreground transition-colors py-2"
                >
                  {item.label}
                </button>
              ))}
              <button
                onClick={() => handleNavClick('#contact')}
                className="text-left text-sm font-medium tracking-widest uppercase text-primary py-2"
              >
                Hire Me
              </button>
            </nav>
          </div>
        )}
      </div>
    </header>
  );
}

export default function Footer() {
  const currentYear = new Date().getFullYear();

  return (
    <footer className="border-t border-border/30 bg-background">
      <div className="container mx-auto px-6 md:px-10 py-8">
        <div className="flex flex-col md:flex-row justify-between items-center gap-3">
          <p className="text-sm text-muted-foreground tracking-wide">
            © {currentYear} Alex Johnson. All rights reserved.
          </p>
          <p className="text-sm text-muted-foreground/50 tracking-widest uppercase text-xs">
            Designed &amp; Built with care
          </p>
        </div>
      </div>
    </footer>
  );
}

import { Helmet } from '@dr.pogodin/react-helmet';
import { motion } from 'motion/react';
import { Github, Linkedin, Twitter, Dribbble, Mail, ArrowDown } from 'lucide-react';

// ─── Animation variants ───────────────────────────────────────────────────────

const fadeUp = {
  hidden: { opacity: 0, y: 32 },
  visible: (delay = 0) => ({
    opacity: 1,
    y: 0,
    transition: { duration: 0.6, delay, ease: 'easeOut' as const },
  }),
};

const fadeIn = {
  hidden: { opacity: 0, y: 20 },
  visible: {
    opacity: 1,
    y: 0,
    transition: { duration: 0.5, ease: 'easeOut' as const },
  },
};

// ─── Dot-grid SVG background ──────────────────────────────────────────────────

function DotGrid() {
  return (
    <svg
      className="absolute inset-0 w-full h-full pointer-events-none"
      aria-hidden="true"
    >
      <defs>
        <pattern id="dots" x="0" y="0" width="28" height="28" patternUnits="userSpaceOnUse">
          <circle cx="1.5" cy="1.5" r="1.5" fill="currentColor" />
        </pattern>
      </defs>
      <rect width="100%" height="100%" fill="url(#dots)" />
    </svg>
  );
}

// ─── Social links ─────────────────────────────────────────────────────────────

const socials = [
  { icon: Github, href: 'https://github.com', label: 'GitHub' },
  { icon: Linkedin, href: 'https://linkedin.com', label: 'LinkedIn' },
  { icon: Twitter, href: 'https://twitter.com', label: 'Twitter / X' },
  { icon: Dribbble, href: 'https://dribbble.com', label: 'Dribbble' },
];

// ─── Skills list ──────────────────────────────────────────────────────────────

const skills = [
  'React & TypeScript',
  'Node.js & APIs',
  'UI / UX Design',
  'Tailwind CSS',
  'Figma & Prototyping',
  'Performance & SEO',
];

// ─── Page ─────────────────────────────────────────────────────────────────────

export default function HomePage() {
  const handleScroll = (id: string) => {
    document.getElementById(id)?.scrollIntoView({ behavior: 'smooth' });
  };

  return (
    <>
      <Helmet>
        <title>Alex Johnson — Creative Developer & Designer</title>
        <meta
          name="description"
          content="Portfolio of Alex Johnson — a creative developer and designer crafting thoughtful digital experiences."
        />
      </Helmet>

      {/* ── HERO ─────────────────────────────────────────────────────────── */}
      <section className="relative min-h-screen flex flex-col justify-center overflow-hidden bg-background">
        {/* Dot-grid texture */}
        <div className="absolute inset-0 text-foreground/[0.04]">
          <DotGrid />
        </div>

        {/* Thin horizontal accent line */}
        <div className="absolute top-0 left-0 right-0 h-px bg-gradient-to-r from-transparent via-primary/40 to-transparent" />

        <div className="relative container mx-auto px-6 md:px-10 pt-32 pb-24">
          {/* Eyebrow */}
          <motion.p
            className="text-xs font-medium tracking-[0.3em] uppercase text-primary mb-8"
            variants={fadeUp}
            initial="hidden"
            animate="visible"
            custom={0}
          >
            Creative Developer &amp; Designer
          </motion.p>

          {/* Name */}
          <motion.h1
            className="font-heading text-[clamp(3.5rem,10vw,7.5rem)] leading-[0.92] tracking-tight text-foreground mb-8 max-w-4xl"
            variants={fadeUp}
            initial="hidden"
            animate="visible"
            custom={0.15}
          >
            Alex
            <br />
            <span className="text-foreground/30">Johnson</span>
          </motion.h1>

          {/* Tagline */}
          <motion.p
            className="text-lg md:text-xl text-foreground/60 font-light max-w-md leading-relaxed mb-12"
            variants={fadeUp}
            initial="hidden"
            animate="visible"
            custom={0.3}
          >
            I craft thoughtful digital experiences — from pixel-perfect interfaces to
            robust, scalable systems.
          </motion.p>

          {/* CTAs */}
          <motion.div
            className="flex flex-wrap items-center gap-6"
            variants={fadeUp}
            initial="hidden"
            animate="visible"
            custom={0.45}
          >
            <button
              onClick={() => handleScroll('contact')}
              className="group inline-flex items-center gap-2 bg-primary text-background text-sm font-semibold tracking-widest uppercase px-8 py-4 hover:bg-primary/90 transition-colors duration-300"
            >
              Get in touch
            </button>
            <button
              onClick={() => handleScroll('about')}
              className="group inline-flex items-center gap-2 text-sm font-medium tracking-widest uppercase text-foreground/60 hover:text-foreground transition-colors duration-300"
            >
              About me
              <ArrowDown
                size={14}
                className="group-hover:translate-y-1 transition-transform duration-300"
              />
            </button>
          </motion.div>
        </div>

        {/* Scroll indicator */}
        <motion.div
          className="absolute bottom-10 left-1/2 -translate-x-1/2 flex flex-col items-center gap-2"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 1.2, duration: 0.6 }}
        >
          <span className="text-[10px] tracking-[0.3em] uppercase text-foreground/30">Scroll</span>
          <motion.div
            className="w-px h-10 bg-gradient-to-b from-foreground/30 to-transparent"
            animate={{ scaleY: [1, 0.4, 1] }}
            transition={{ duration: 2, repeat: Infinity, ease: 'easeInOut' as const }}
          />
        </motion.div>
      </section>

      {/* ── ABOUT ────────────────────────────────────────────────────────── */}
      <section id="about" className="bg-background py-28 md:py-36">
        <div className="container mx-auto px-6 md:px-10">
          {/* Section label */}
          <motion.p
            className="text-xs font-medium tracking-[0.3em] uppercase text-primary mb-16"
            variants={fadeIn}
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true }}
          >
            About
          </motion.p>

          <div className="grid md:grid-cols-2 gap-16 md:gap-24 items-start">
            {/* Bio */}
            <motion.div
              variants={fadeIn}
              initial="hidden"
              whileInView="visible"
              viewport={{ once: true }}
            >
              <h2 className="font-heading text-4xl md:text-5xl text-foreground leading-tight mb-8">
                Building at the intersection of design &amp; code.
              </h2>
              <div className="space-y-5 text-foreground/60 leading-relaxed">
                <p>
                  I'm a full-stack developer and designer with over 6 years of experience
                  building products that people love. My work spans from early-stage startups
                  to established companies, always with a focus on clarity, performance, and
                  craft.
                </p>
                <p>
                  I believe the best digital experiences come from a deep understanding of
                  both the technical and human sides of a problem. I work closely with
                  founders, product teams, and engineers to turn complex ideas into elegant,
                  functional solutions.
                </p>
                <p>
                  When I'm not building, you'll find me exploring generative art, contributing
                  to open source, or writing about design systems and developer experience.
                </p>
              </div>
            </motion.div>

            {/* Skills + decorative */}
            <motion.div
              variants={fadeIn}
              initial="hidden"
              whileInView="visible"
              viewport={{ once: true }}
              transition={{ delay: 0.15 }}
              className="space-y-10"
            >
              {/* Skills list */}
              <div>
                <p className="text-xs tracking-[0.25em] uppercase text-foreground/40 mb-6">
                  Expertise
                </p>
                <ul className="space-y-3">
                  {skills.map((skill, i) => (
                    <li
                      key={skill}
                      className="flex items-center gap-4 text-foreground/70 text-sm"
                    >
                      <span
                        className="text-primary font-mono text-xs"
                        aria-hidden="true"
                      >
                        {String(i + 1).padStart(2, '0')}
                      </span>
                      <span className="flex-1 border-b border-border/20 pb-3">{skill}</span>
                    </li>
                  ))}
                </ul>
              </div>

              {/* Decorative stat block */}
              <div className="grid grid-cols-2 gap-px border border-border/20">
                {[
                  { value: '6+', label: 'Years experience' },
                  { value: '40+', label: 'Projects shipped' },
                  { value: '15+', label: 'Happy clients' },
                  { value: '∞', label: 'Cups of coffee' },
                ].map((stat) => (
                  <div
                    key={stat.label}
                    className="p-6 border border-border/10 bg-card/30"
                  >
                    <p className="font-heading text-3xl text-foreground mb-1">{stat.value}</p>
                    <p className="text-xs text-foreground/40 tracking-wide">{stat.label}</p>
                  </div>
                ))}
              </div>
            </motion.div>
          </div>
        </div>
      </section>

      {/* ── CONTACT ──────────────────────────────────────────────────────── */}
      <section id="contact" className="bg-background py-28 md:py-36 relative overflow-hidden">
        {/* Subtle background accent */}
        <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
          <div className="w-[600px] h-[600px] rounded-full bg-primary/[0.03] blur-3xl" />
        </div>

        <div className="relative container mx-auto px-6 md:px-10">
          <motion.p
            className="text-xs font-medium tracking-[0.3em] uppercase text-primary mb-8"
            variants={fadeIn}
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true }}
          >
            Contact
          </motion.p>

          <motion.h2
            className="font-heading text-5xl md:text-7xl text-foreground leading-tight mb-6 max-w-2xl"
            variants={fadeIn}
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true }}
          >
            Let's work together.
          </motion.h2>

          <motion.p
            className="text-foreground/50 text-lg max-w-md mb-14 leading-relaxed"
            variants={fadeIn}
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true }}
          >
            Have a project in mind or just want to say hello? My inbox is always open.
          </motion.p>

          {/* Email link */}
          <motion.a
            href="mailto:hello@alexjohnson.dev"
            className="group inline-flex items-center gap-3 text-2xl md:text-3xl font-heading text-foreground/80 hover:text-primary transition-colors duration-300 mb-16"
            variants={fadeIn}
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true }}
          >
            <Mail size={28} className="text-primary shrink-0" />
            <span className="border-b border-foreground/20 group-hover:border-primary transition-colors duration-300 pb-1">
              hello@alexjohnson.dev
            </span>
          </motion.a>

          {/* Social icons */}
          <motion.div
            className="flex items-center gap-6"
            variants={fadeIn}
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true }}
          >
            <p className="text-xs tracking-[0.25em] uppercase text-foreground/30 mr-2">
              Find me on
            </p>
            {socials.map(({ icon: Icon, href, label }) => (
              <motion.a
                key={label}
                href={href}
                target="_blank"
                rel="noopener noreferrer"
                aria-label={label}
                className="text-foreground/40 hover:text-primary transition-colors duration-200"
                whileHover={{ scale: 1.1 }}
                transition={{ duration: 0.15, ease: 'easeOut' as const }}
              >
                <Icon size={22} strokeWidth={1.5} />
              </motion.a>
            ))}
          </motion.div>
        </div>
      </section>
    </>
  );
}
